/**
 * File system helpers.
 *
 * Rule: SolarOps never erases or replaces what it did not create. Existing
 * folders keep their permissions, and generated files are only rewritten
 * when they carry SolarOps's marker (see writeManagedFile).
 */
import fs from 'node:fs/promises';
import { constants as fsConstants } from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { conflict } from './errors.js';

/**
 * Create a directory (and parents) with the given mode. An existing
 * directory is left exactly as it is (permissions included).
 *
 * @param {string} directory
 * @param {number} [mode]
 * @returns {Promise<boolean>} true when the directory was created
 */
export async function ensureDirectory(directory, mode = 0o755) {
  if (await pathExists(directory)) {
    return false;
  }

  await fs.mkdir(directory, { recursive: true, mode });
  // mkdir applies the umask: set the exact mode on what we just created.
  await fs.chmod(directory, mode);

  return true;
}

/**
 * Write a file atomically: write to a temporary file in the same folder,
 * then rename it. Readers never see a half-written file.
 *
 * @param {string} filePath
 * @param {string} content
 * @param {number} [mode]
 */
export async function writeFileAtomic(filePath, content, mode = 0o644) {
  const temporaryPath = `${filePath}.${crypto.randomBytes(4).toString('hex')}.tmp`;

  await fs.writeFile(temporaryPath, content, { mode });
  await fs.chmod(temporaryPath, mode);
  await fs.rename(temporaryPath, filePath);
}

/**
 * Whether a file was generated by SolarOps (contains its marker), or does
 * not exist at all.
 *
 * @param {string} filePath
 * @param {string} marker text every SolarOps-generated version contains
 * @returns {Promise<boolean>}
 */
export async function isManagedFile(filePath, marker) {
  const content = await readFileOrNull(filePath);

  return content === null || content.includes(marker);
}

/**
 * Write a generated file, refusing to replace a file SolarOps did not
 * write itself (e.g. an nginx.conf that existed before the project was
 * created in SolarOps).
 *
 * @param {string} filePath
 * @param {string} content must contain the marker
 * @param {object} options
 * @param {string} options.marker
 * @param {number} [options.mode]
 */
export async function writeManagedFile(filePath, content, { marker, mode = 0o644 }) {
  if (!(await isManagedFile(filePath, marker))) {
    throw conflict(
      `${filePath} already exists and was not generated by SolarOps: it was left untouched. Move it away to let SolarOps manage this file.`,
    );
  }

  await writeFileAtomic(filePath, content, mode);
}

/**
 * @param {string} filePath
 * @returns {Promise<boolean>}
 */
export async function pathExists(filePath) {
  try {
    await fs.access(filePath, fsConstants.F_OK);
    return true;
  } catch {
    return false;
  }
}

/**
 * Read a file, or return null when it does not exist.
 *
 * @param {string} filePath
 * @returns {Promise<string|null>}
 */
export async function readFileOrNull(filePath) {
  try {
    return await fs.readFile(filePath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      return null;
    }
    throw error;
  }
}

/**
 * Whether `child` is located inside `parent` (after resolving both).
 * Used to make sure we never touch files outside a project folder.
 *
 * @param {string} child
 * @param {string} parent
 * @returns {boolean}
 */
export function isPathInside(child, parent) {
  const relative = path.relative(path.resolve(parent), path.resolve(child));

  if (relative === '') {
    return false;
  }

  return !relative.startsWith('..') && !path.isAbsolute(relative);
}

/**
 * Return the last `maxLines` lines of a (possibly large) text file without
 * reading it entirely.
 *
 * @param {string} filePath
 * @param {number} maxLines
 * @returns {Promise<string>}
 */
export async function tailFile(filePath, maxLines) {
  let handle;

  try {
    handle = await fs.open(filePath, 'r');
  } catch (error) {
    if (error.code === 'ENOENT') {
      return '';
    }
    throw error;
  }

  try {
    const { size } = await handle.stat();
    const readSize = Math.min(size, 512 * 1024);
    const buffer = Buffer.alloc(readSize);

    await handle.read(buffer, 0, readSize, size - readSize);

    const lines = buffer.toString('utf8').split('\n');

    return lines.slice(-maxLines - 1).join('\n');
  } finally {
    await handle.close();
  }
}
